predicted_sql:
SELECT MAX(Share) AS Max_Share, MIN(Share) AS Min_Share 
FROM performance 
WHERE Type != 'Live final';

SELECT Owners.first_name, Owners.last_name, Dogs.size_code
FROM Owners
JOIN Dogs ON Owners.owner_id = Dogs.owner_id;

SELECT ranking_date, COUNT(DISTINCT tours) AS total_tours
FROM rankings
GROUP BY ranking_date;

SELECT COUNT(*) 
FROM countrylanguage 
WHERE Language = 'Spanish' AND IsOfficial = 'T';

SELECT Maker, Id FROM car_makers WHERE Id IN (
    SELECT Maker FROM car_names GROUP BY Maker HAVING COUNT(*) > 3
)

SELECT Directed_by, COUNT(*) as Cartoon_count
FROM Cartoon
GROUP BY Directed_by;

SELECT Template_Type_Code, COUNT(Template_ID) AS Number_of_Templates
FROM Templates
GROUP BY Template_Type_Code;
